<?php
namespace app\controller\Api;
use app\controller\Api\Concerns\Responds; use app\server\expense\ExpenseService; use support\Request; use support\Response; use Throwable;
final class ExpenseController {use Responds; private function run(callable $f):Response{try{return $this->ok($f());}catch(Throwable $e){$s=in_array($e->getCode(),[403,404,409,422],true)?$e->getCode():500;return $this->fail($s*100,$e->getMessage(),$s);}} public function options(Request $r):Response{return $this->run(fn()=>(new ExpenseService)->options());} public function list(Request $r):Response{return $this->run(fn()=>(new ExpenseService)->list($r->all()));} public function detail(Request $r):Response{return $this->run(fn()=>(new ExpenseService)->detail((int)$r->input('id')));} public function save(Request $r):Response{return $this->run(fn()=>(new ExpenseService)->save($r->all()));} public function submit(Request $r):Response{return $this->run(fn()=>(new ExpenseService)->submit((int)$r->input('id'),(string)$r->input('request_id')));} public function export(Request $r):Response{return $this->run(fn()=>(new ExpenseService)->export((int)$r->input('id'),(string)$r->input('format','docx')));}}
